// --- GlitchText Component ---
// (Keep as is, relies on React state and effects)
const GlitchText = ({ text }) => {
  const [glitchedText, setGlitchedText] = useState(text);
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true); // Indicate component has mounted
  }, []);

  useEffect(() => {
    if (!isMounted) return; // Only run effects on the client after mount

    let intervalId = null;
    let timeoutId = null;

    const glitch = () => {
      let newText = '';
      for (let i = 0; i < text.length; i++) {
        // Glitch more characters, more often
        newText += Math.random() > 0.7 ? String.fromCharCode(33 + Math.floor(Math.random() * 94)) : text[i];
      }
      setGlitchedText(newText);
      timeoutId = setTimeout(() => setGlitchedText(text), 40 + Math.random() * 40); // Revert faster
    };

    // Start glitching immediately on mount for more effect
    glitch();

    intervalId = setInterval(glitch, 1500 + Math.random() * 2000); // Glitch more frequently

    return () => {
      if (intervalId) clearInterval(intervalId);
      if (timeoutId) clearTimeout(timeoutId);
    };
  }, [text, isMounted]); // Depend on isMounted

  return (
      <span className="inline-block min-h-[1em]" aria-label={text}>
        {isMounted ? glitchedText : text}
      </span>
  );
};

