// --- Particle Background Component ---
// (Keep as is, uses standard canvas API and React effects)
const ParticleBackground = () => {
      useEffect(() => {
          const canvas = document.getElementById('particle-canvas');
          if (!canvas) return;
          const ctx = canvas.getContext('2d');
          if (!ctx) return;

          let particles = [];
          let mouse = { x: null, y: null, radius: (canvas.height / 120) * (canvas.width / 120) }; // Increase interaction radius

          const handleMouseMove = (event) => {
             mouse.x = event.clientX;
             mouse.y = event.clientY;
          };
          window.addEventListener('mousemove', handleMouseMove);

          const handleMouseOut = () => {
             mouse.x = null;
             mouse.y = null;
          }
          window.addEventListener('mouseout', handleMouseOut);


          canvas.width = window.innerWidth;
          canvas.height = document.documentElement.scrollHeight; // Use scroll height for full page coverage

          const createParticles = () => {
              particles = [];
               // Adjust density based on viewport area, but cap it for performance
              const particleCount = Math.min(200, Math.floor((window.innerWidth * window.innerHeight) / 15000));
              for (let i = 0; i < particleCount; i++) {
                   const size = Math.random() * 1.5 + 0.5; // Smaller particles
                   const x = Math.random() * (canvas.width - size * 2) + size;
                   const y = Math.random() * (canvas.height - size * 2) + size;
                   const directionX = (Math.random() * 0.4 - 0.2); // Slower speed
                   const directionY = (Math.random() * 0.4 - 0.2);
                  particles.push({
                      x: x,
                      y: y,
                      size: size,
                      speedX: directionX,
                      speedY: directionY,
                      originalX: x,
                      originalY: y,
                      density: (Math.random() * 30) + 1 // For mouse interaction
                  });
              }
          };

          let animationFrameId;
          const animateParticles = () => {
              ctx.clearRect(0, 0, canvas.width, canvas.height);
              ctx.fillStyle = 'hsla(var(--foreground) / 0.1)'; // Subtle particle color

              particles.forEach(p => {
                 // Mouse interaction
                 let dx = mouse.x - p.x;
                 let dy = mouse.y - p.y;
                 let distance = Math.sqrt(dx*dx + dy*dy);
                 let forceDirectionX = dx / distance;
                 let forceDirectionY = dy / distance;
                 let maxDistance = mouse.radius;
                 let force = (maxDistance - distance) / maxDistance; // Closer = stronger force
                 let directionX = forceDirectionX * force * p.density * 0.6; // Adjust multiplier for effect strength
                 let directionY = forceDirectionY * force * p.density * 0.6;

                 if (distance < mouse.radius) {
                    p.x -= directionX;
                    p.y -= directionY;
                    // Add a slight repulsion from other particles when close to mouse? (more complex)
                 } else {
                    // Return to original position gently
                    if (p.x !== p.originalX) {
                        let dx = p.x - p.originalX;
                        p.x -= dx/20; // Slow return
                    }
                     if (p.y !== p.originalY) {
                        let dy = p.y - p.originalY;
                        p.y -= dy/20; // Slow return
                    }
                    // Or continue drifting slightly
                    // p.x += p.speedX;
                    // p.y += p.speedY;
                 }

                  // Boundary check (bounce off edges smoothly)
                  if (p.x + p.size > canvas.width || p.x - p.size < 0) {
                     p.speedX = -p.speedX * 0.8; // Dampen bounce
                     // Ensure particle stays within bounds after bounce
                     if (p.x + p.size > canvas.width) p.x = canvas.width - p.size;
                     if (p.x - p.size < 0) p.x = p.size;
                  }
                  if (p.y + p.size > canvas.height || p.y - p.size < 0) {
                      p.speedY = -p.speedY * 0.8; // Dampen bounce
                     // Ensure particle stays within bounds after bounce
                     if (p.y + p.size > canvas.height) p.y = canvas.height - p.size;
                      if (p.y - p.size < 0) p.y = p.size;
                  }

                  // Add subtle drift even when mouse isn't interacting
                   if (distance >= mouse.radius) {
                        p.x += p.speedX;
                        p.y += p.speedY;
                   }


                  ctx.beginPath();
                  ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                  ctx.fill();
              });

              animationFrameId = requestAnimationFrame(animateParticles);
          };

          const handleResize = () => {
               cancelAnimationFrame(animationFrameId); // Stop previous animation loop
               canvas.width = window.innerWidth;
               canvas.height = document.documentElement.scrollHeight;
                mouse.radius = (canvas.height / 120) * (canvas.width / 120);
               createParticles();
               animateParticles(); // Start new animation loop
          };

          // Debounce resize handler
          let resizeTimeout;
          const debouncedResize = () => {
            clearTimeout(resizeTimeout);
            resizeTimeout = setTimeout(handleResize, 150);
          }

          createParticles();
          animateParticles();

          window.addEventListener('resize', debouncedResize);
          // Also recalculate on scroll if height changes dynamically (might be overkill)
          // window.addEventListener('scroll', handleResize);

          return () => {
            cancelAnimationFrame(animationFrameId);
            window.removeEventListener('resize', debouncedResize);
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseout', handleMouseOut);
            // window.removeEventListener('scroll', handleResize);
            clearTimeout(resizeTimeout);
          }

      }, []);

      // Apply styles directly to the canvas element
      return <canvas id="particle-canvas" style={{ position: 'fixed', top: 0, left: 0, zIndex: -4, pointerEvents: 'none' }}></canvas>;
   };


