import React, { useState, useEffect } from 'react';
// import Link from 'next/link'; // Use standard anchor tags for section scrolling
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '../../lib/utils'; // Adjust path
import { Button } from '../ui/button'; // Adjust path
import { Menu, X, User, Briefcase, Mail } from 'lucide-react';

// Nav Items (Keep as is)
const navItems = [
  { id: 'about', label: 'About', icon: User },
  { id: 'services', label: 'Services', icon: Briefcase },
  { id: 'contact', label: 'Contact', icon: Mail },
];

export function Navbar() {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [activeSection, setActiveSection] = useState(null);

  useEffect(() => {
    const handleScroll = () => {
      const currentScrollY = window.scrollY;
      setScrolled(currentScrollY > 20);

      // --- Active Section Logic ---
      let foundSection = null;
      const buffer = window.innerHeight * 0.4; // 40% of viewport height

      for (const item of navItems) {
        const element = document.getElementById(item.id);
        if (element) {
          const elementTop = element.offsetTop;
          const elementBottom = elementTop + element.offsetHeight;

          if (
            (currentScrollY >= elementTop - buffer && currentScrollY < elementBottom - buffer)
          ) {
             foundSection = item.id;
             break;
          }
        }
      }
        // Default to null if nothing else matches clearly
        // if (foundSection === null && currentScrollY < window.innerHeight * 0.5) {
        //      foundSection = navItems[0]?.id;
        // }


      setActiveSection(foundSection);
    };


    window.addEventListener('scroll', handleScroll, { passive: true });
    handleScroll(); // Initial check

    return () => window.removeEventListener('scroll', handleScroll);
  }, []);


  const scrollToSection = (id) => {
    const element = document.getElementById(id);
    if (element) {
      const offset = 80;
      const bodyRect = document.body.getBoundingClientRect().top;
      const elementRect = element.getBoundingClientRect().top;
      const elementPosition = elementRect - bodyRect;
      const offsetPosition = elementPosition - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth',
      });
    }
    setIsOpen(false); // Close mobile menu on click
  };

  // Motion Variants (Keep as is)
  const navContainerVariants = {
    hidden: { y: -100, opacity: 0 },
    visible: { y: 0, opacity: 1, transition: { type: 'spring', stiffness: 80, damping: 15, delay: 0.5 } },
  };

  const mobileMenuVariants = {
    closed: { opacity: 0, y: "-20%" },
    open: { opacity: 1, y: 0, transition: { type: 'tween', duration: 0.3, ease: 'easeInOut' } },
  };

   const mobileNavItemVariants = {
      closed: { opacity: 0, x: -20 },
      open: (i) => ({
          opacity: 1,
          x: 0,
          transition: { delay: i * 0.05 + 0.1, type: 'spring', stiffness: 100 }
      })
  }

  return (
    <motion.nav
      variants={navContainerVariants}
      initial="hidden"
      animate="visible"
      className={cn(
        'fixed top-0 left-0 right-0 z-50 transition-colors duration-300',
         scrolled ? 'bg-background/80 backdrop-blur-lg border-b border-border/50 shadow-sm' : 'bg-transparent border-b border-transparent'
      )}
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-20">
          {/* Logo/Brand */}
          <div className="flex-shrink-0">
             <a // Use <a> for smooth scrolling
               href="#hero"
               onClick={(e) => { e.preventDefault(); scrollToSection('hero'); }}
               className="text-2xl font-bold font-sans text-primary hover:text-accent transition-colors duration-300 tracking-tight"
             >
               GK<span className="text-accent">.</span>
             </a>
          </div>

          {/* Desktop Navigation */}
          <div className="hidden md:flex items-center space-x-2">
            {navItems.map((item) => (
              <a
                key={item.id}
                href={`#${item.id}`}
                onClick={(e) => {
                  e.preventDefault();
                  scrollToSection(item.id);
                }}
                className={cn(
                  'relative px-4 py-2 rounded-md text-sm font-medium transition-all duration-300 group',
                  activeSection === item.id
                    ? 'text-accent'
                    : 'text-muted-foreground hover:text-primary'
                )}
              >
                {item.label}
                <span className={cn(
                    "absolute bottom-0 left-0 right-0 h-[2px] transition-transform duration-300 ease-out origin-center",
                    activeSection === item.id ? "scale-x-100 bg-accent" : "scale-x-0 group-hover:scale-x-100 bg-primary"
                )} />
              </a>
            ))}
          </div>

          {/* Mobile Menu Button */}
          <div className="flex items-center md:hidden">
            <Button
              variant="ghost"
              size="icon"
              onClick={() => setIsOpen(!isOpen)}
              className="text-primary hover:text-accent focus:outline-none"
              aria-label="Toggle menu"
            >
              {isOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
            </Button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            variants={mobileMenuVariants}
            initial="closed"
            animate="open"
            exit="closed"
            className="md:hidden absolute top-full left-0 right-0 bg-background/90 backdrop-blur-md shadow-lg pb-4 border-t border-border/50 overflow-hidden"
          >
            <div className="px-5 pt-3 space-y-2">
              {navItems.map((item, i) => (
                 <motion.a
                  key={item.id}
                  href={`#${item.id}`}
                  custom={i}
                  variants={mobileNavItemVariants}
                  initial="closed"
                  animate="open"
                  exit="closed"
                  onClick={(e) => {
                    e.preventDefault();
                    scrollToSection(item.id);
                  }}
                  className={cn(
                    'flex items-center gap-3 px-3 py-3 rounded-md text-base font-medium transition-colors',
                    activeSection === item.id
                      ? 'bg-accent text-accent-foreground'
                      : 'text-primary hover:bg-secondary'
                  )}
                >
                  <item.icon className="h-5 w-5" />
                  {item.label}
                 </motion.a>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.nav>
  );
}
